import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.Boholvbs.js";const i="/docs/assets/story-map-edit.NSlrNFRc.png",n="/docs/assets/story-map-edit2.BS1LuG3q.png",r="/docs/assets/story-map-edit3.BhGyTX1W.png",l="/docs/assets/story-map-edit4.DmZVbLvV.png",p="/docs/assets/story-map-edit5.Dys6BJII.png",h="/docs/assets/story-map-edit6.C3EGy36Y.png",d="/docs/assets/story-map-edit7.CfT8oZ2F.png",c="/docs/assets/story-map-edit8.Cmsra8tE.png",g="/docs/assets/story-map-edit9.DLju1YEX.png",S=JSON.parse('{"title":"Story Map","description":"","frontmatter":{},"headers":[],"relativePath":"story-map.md","filePath":"story-map.md"}'),m={name:"story-map.md"};function y(u,t,k,b,f,_){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="story-map" tabindex="-1">Story Map <a class="header-anchor" href="#story-map" aria-label="Permalink to &quot;Story Map&quot;">​</a></h1><p>Story Map is a way of making an interactive storytelling with customized maps and layers. You are able to select specific locations and related layers and texts to these locations. This will generate a map that, when the page is scrolled, will change from one location/layer/text to another. This group of location, layer and text are called <strong>Slide</strong>.</p><h2 id="creating-a-story-map" tabindex="-1">Creating a Story Map <a class="header-anchor" href="#creating-a-story-map" aria-label="Permalink to &quot;Creating a Story Map&quot;">​</a></h2><p>Story Map is a custom post type in JEO Plugin. When creating one, you&#39;ll be asked for a map. All of the layers that you are going to use in your Story Map come from this previous selected map. Also, Story Map has a <code>Navigate function</code>, which we will talk about later. This Navigate function also uses this selected map to work.</p><p><img src="'+i+'" alt="Story Map edit"></p><h3 id="story-settings" tabindex="-1">Story settings <a class="header-anchor" href="#story-settings" aria-label="Permalink to &quot;Story settings&quot;">​</a></h3><p>Here you can set a description for your story map which will be shown at the beginning of the post, with the title and publish date. You can also define whether or not your story map will have an introduction and a <code>Navigate map button</code>.</p><p><strong>All the text fields has a buit-in Rich Text Editor. This means that you can put bold text, links, lists, etc inside your text field.</strong></p><p><code>Navigate map button</code> appears at the end of a Story Map and allows the user to navigate through the map. This map will follow all the settings of the previous selected.</p><p><img src="'+n+'" alt="Story Map edit"></p><h3 id="slides-settings" tabindex="-1">Slides settings <a class="header-anchor" href="#slides-settings" aria-label="Permalink to &quot;Slides settings&quot;">​</a></h3><p>A Story Map slide contains a title, content, location and selected layers (The order of the layers will always follow the map layers order that were defined when creating this map). You can remove a slide by clicking on <strong>Remove</strong> button, preview the map in a slide clicking on <strong>Preview</strong> button, and set the location to the current slide clicking on <strong>Lock current spot</strong> button. You can see what&#39;s the current slide at the top-right side of the block.</p><p>You can pick a location to a slide by dragging the map with left mouse button and changing its peaching and bearing by dragging the map with right mouse button.</p><p><img src="'+r+'" alt="Story Map edit"></p><p><img src="'+l+'" alt="Story Map edit"></p><p>Slides can be rearranged by clicking on <code>=</code> icon and dragging it to put the slide in another position.</p><p><img src="'+p+'" alt="Story Map edit"></p><h2 id="looking-at-a-story-map" tabindex="-1">Looking at a Story Map <a class="header-anchor" href="#looking-at-a-story-map" aria-label="Permalink to &quot;Looking at a Story Map&quot;">​</a></h2><p>This is how a Story Map look in a post:</p><p><img src="'+h+'" alt="Story Map edit"></p><p>Clicking on <strong>START</strong> will take the user to the first slide. Clicking on <strong>skip intro</strong> will take the user to the map itself so they can navigate through it (this button is only available if the navigate setting is enabled in story map settings). These buttons, the title, description and publish date only appears if <code>Shows story map introduction</code> is enabled. If it isn&#39;t, the story map starts on the first slide.</p><p><img src="'+d+'" alt="Story Map edit"></p><p>While the page is scrolled, the current slide changes to the next one and the map do a transition to the next location and change its layers. At the end of the storytelling, if the correct setting is enabled, a <strong>NAVIGATE THE MAP</strong> button will shows up. Clicking on it will take the user to the map itself and allowing they to interact with it.</p><p><img src="'+c+'" alt="Story Map edit"></p><p><img src="'+g+'" alt="Story Map edit"></p><h2 id="theme-integration" tabindex="-1">Theme integration <a class="header-anchor" href="#theme-integration" aria-label="Permalink to &quot;Theme integration&quot;">​</a></h2><p>The public story map output includes a stable map container for theme integrations:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;story-map-element jeo-storymap-map js-jeo-storymap-map&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Themes that need to position or measure the story map should target <code>jeo-storymap-map</code> or <code>js-jeo-storymap-map</code> instead of runtime classes such as <code>mapboxgl-map</code> or <code>maplibregl-map</code>. The JEO classes are present before the map runtime initializes, while runtime classes are added asynchronously by the map library.</p>',29)])])}const E=e(m,[["render",y]]);export{S as __pageData,E as default};
